// The entry point of the test binary built by bin/fast-test.sh.
// It does what the runner generated by SwiftPM does when it is called with
// `--testing-library swift-testing`. It leaves out XCTest, so it compiles in
// about 0.1 seconds instead of 1 second, and it is compiled once at image build.
import Testing

@main
struct Runner {
    @_silgen_name("$ss13_runAsyncMainyyyyYaKcF")
    private static func _runAsyncMain(_ asyncFun: @Sendable @escaping () async throws -> ())

    static func main() {
        _runAsyncMain {
            await Testing.__swiftPMEntryPoint() as Never
        }
    }
}
